466. pub open spec fn installed_reconcile_model<R, S, K, EReq, EResp>() -> ReconcileModel
467.     where
468.         R: Reconciler<S, K, EReq, EResp>,
469.         K: CustomResourceView,
470.         S: Marshallable,
471.         EReq: Marshallable,
472.         EResp: Marshallable,
473. {
474.     ReconcileModel {
475.         kind: K::kind(),
476.         init: || R::reconcile_init_state().marshal(),
477.         transition: |obj, resp_o, s| {
478.             let obj_um = K::unmarshal(obj)->Ok_0;
479.             let resp_o_um = match resp_o {
480.                 None => None,
481.                 Some(resp) => Some(match resp {
482.                     ResponseContent::KubernetesResponse(api_resp) => ResponseView::<EResp>::KResponse(api_resp),
483.                     ResponseContent::ExternalResponse(ext_resp) => ResponseView::<EResp>::ExternalResponse(EResp::unmarshal(ext_resp)->Ok_0),
484.                 })
485.             };
486.             let s_um = S::unmarshal(s)->Ok_0;
487.             let (s_prime_um, req_o_um) = R::reconcile_core(obj_um, resp_o_um, s_um);
488.             (s_prime_um.marshal(), match req_o_um {
489.                 None => None,
490.                 Some(req) => Some(match req {
491.                     RequestView::<EReq>::KRequest(api_req) => RequestContent::KubernetesRequest(api_req),
492.                     RequestView::<EReq>::ExternalRequest(ext_req) => RequestContent::ExternalRequest(ext_req.marshal()),
493.                 })
494.             })
495.         },
496.         done: |s| R::reconcile_done(S::unmarshal(s)->Ok_0),
497.         error: |s| R::reconcile_error(S::unmarshal(s)->Ok_0),
498.     }
499. }
500. 
501. }
