     spec fn reconcile_init_state() -> S;

     spec fn reconcile_core(cr: K, resp_o: Option<ResponseView<EResp>>, state: S) -> (S, Option<RequestView<EReq>>);

     spec fn reconcile_done(state: S) -> bool;

     spec fn reconcile_error(state: S) -> bool;

 }



